import{_ as s,o as t,c as o,ag as a}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Optional: set up your own computer","description":"","frontmatter":{"source":"setup/local-setup.md"},"headers":[],"relativePath":"setup/local-setup.md","filePath":"setup/local-setup.md"}'),i={name:"setup/local-setup.md"};function n(r,e,l,p,h,d){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="optional-set-up-your-own-computer" tabindex="-1">Optional: set up your own computer <a class="header-anchor" href="#optional-set-up-your-own-computer" aria-label="Permalink to &quot;Optional: set up your own computer&quot;">​</a></h1><blockquote><p>You don&#39;t need this page to complete the course. Everything runs in GitHub Codespaces. Use it if you want to work offline, have run out of Codespaces hours, or want to keep working after the course ends.</p></blockquote><p>Setting up takes 30–60 minutes. You&#39;ll install three things:</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it is</th><th>Why you need it</th></tr></thead><tbody><tr><td><strong>VS Code</strong></td><td>The code editor, the same one you use in Codespaces</td><td>Editing, Source Control, GitHub Copilot</td></tr><tr><td><strong>Git</strong></td><td>The version-control tool behind GitHub</td><td>Commits, history, push and pull</td></tr><tr><td><strong>Node.js</strong> (22 LTS; minimum 20.12)</td><td>Runs JavaScript outside the browser, plus <strong>npm</strong>, its package manager</td><td>Running the tests from week 4, and the starters from week 9</td></tr></tbody></table><p><strong>LTS</strong> means &quot;long-term support&quot;: the stable version most people should use. The course uses <strong>Node.js 22 LTS</strong>. The starters need at least version 20.12, and Node 20 no longer gets security updates, so install 22 or a newer LTS. Some AI command-line tools need a recent version too.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>On your own computer, an AI agent can reach your own files.</strong> Agents have overwritten real users&#39; files and, in one case, wiped a whole drive (<a href="https://incidentdatabase.ai/cite/1178/" target="_blank" rel="noreferrer">AI Incident Database #1178</a>; <a href="https://www.tomshardware.com/tech-industry/artificial-intelligence/googles-agentic-ai-wipes-users-entire-hard-drive-without-permission-after-misinterpreting-instructions-to-clear-a-cache-i-am-deeply-deeply-sorry-this-is-a-critical-failure-on-my-part" target="_blank" rel="noreferrer">Tom&#39;s Hardware</a>). Keep course projects in one dedicated folder, open only a single project in the editor, and do agent work (weeks 11–16) in a Codespace unless your instructor says otherwise. Wherever you run an agent, approvals stay on and you never use autopilot or skip-permissions modes (safety contract <a href="./safety-contract.html#9-agents-dont-publish-and-untrusted-content-never-shares-a-session-with-my-secrets">rule 9</a>). See <a href="#when-to-stay-in-codespaces">When to stay in Codespaces</a>.</p></div><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li><p><strong>Git.</strong> Open the <strong>Terminal</strong> app and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xcode-select</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div><p>Click <strong>Install</strong> in the window that appears. This installs Apple&#39;s command-line tools, which include Git and Python 3. If it says they&#39;re already installed, you&#39;re done.</p></li><li><p><strong>VS Code.</strong> Download it from <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">code.visualstudio.com</a>, open the downloaded file, and drag <strong>Visual Studio Code</strong> into <strong>Applications</strong>. Open it once, then open the Command Palette (<code>Cmd+Shift+P</code>) and run <strong>Shell Command: Install &#39;code&#39; command in PATH</strong>. You can then type <code>code .</code> in Terminal to open a folder.</p></li><li><p><strong>Node.js.</strong> Choose one:</p><ul><li><strong>Official installer (simplest):</strong> download the <strong>LTS</strong> macOS installer from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">nodejs.org</a> and run it.</li><li><strong>A version manager (flexible):</strong> tools such as <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a> or <a href="https://github.com/Schniz/fnm" target="_blank" rel="noreferrer">fnm</a> let you switch Node versions per project. Follow their install instructions, then run <code>nvm install 22</code> (or <code>fnm install 22</code>).</li></ul></li></ol><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li><p><strong>Git.</strong> Download <strong>Git for Windows</strong> from <a href="https://git-scm.com/downloads/win" target="_blank" rel="noreferrer">git-scm.com</a> and run the installer. The default options are fine. When asked for a default editor, you can pick <strong>Visual Studio Code</strong>. The installer includes <strong>Git Credential Manager</strong>, which handles signing in to GitHub, and <strong>Git Bash</strong>, a terminal that understands the same commands as Codespaces.</p></li><li><p><strong>VS Code.</strong> Download the <strong>User Installer</strong> from <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">code.visualstudio.com</a> and run it. Tick <strong>Add &quot;Open with Code&quot; action</strong> and <strong>Add to PATH</strong> when offered.</p></li><li><p><strong>Node.js.</strong> Download the <strong>LTS</strong> Windows installer (<code>.msi</code>) from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">nodejs.org</a> and run it with the default options. Or, in PowerShell:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">winget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OpenJS.NodeJS.LTS</span></span></code></pre></div></li><li><p><strong>Python (only for previewing static sites).</strong> Install it from <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">python.org</a> and tick <strong>Add python.exe to PATH</strong>. On Windows the command is usually <code>py</code> or <code>python</code> rather than <code>python3</code>.</p></li></ol><h3 id="windows-notes" tabindex="-1">Windows notes <a class="header-anchor" href="#windows-notes" aria-label="Permalink to &quot;Windows notes&quot;">​</a></h3><ul><li><strong>Which terminal?</strong> VS Code&#39;s built-in terminal opens <strong>PowerShell</strong> by default. Most commands in this course work there. A few differ: to copy a file, use <code>Copy-Item .env.example .env</code> instead of <code>cp .env.example .env</code>. To get the same commands as in Codespaces, switch the terminal to <strong>Git Bash</strong> (the <strong>⌄</strong> next to the <strong>+</strong> in the terminal panel).</li><li><strong>WSL (optional).</strong> The Windows Subsystem for Linux runs a real Linux system inside Windows. You don&#39;t need it for this course. Some open-source AI terminal tools recommend it, though, so if you try those later, see Microsoft&#39;s <a href="https://learn.microsoft.com/windows/wsl/install" target="_blank" rel="noreferrer">WSL install guide</a>.</li><li><strong>Line endings.</strong> If git warns about <code>LF will be replaced by CRLF</code>, that&#39;s normal on Windows and harmless for this course.</li></ul><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>Instructions for Ubuntu and Debian; other distributions have equivalents.</p><ol><li><p><strong>Git and Python:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span></span></code></pre></div></li><li><p><strong>VS Code.</strong> Download the <code>.deb</code> package from <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">code.visualstudio.com</a> and install it, for example with <code>sudo apt install ./code_*.deb</code> from the download folder.</p></li><li><p><strong>Node.js.</strong> Your distribution&#39;s own <code>nodejs</code> package is often too old. Use a version manager such as <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a>, then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span></code></pre></div></li></ol><h2 id="check-your-installation" tabindex="-1">Check your installation <a class="header-anchor" href="#check-your-installation" aria-label="Permalink to &quot;Check your installation&quot;">​</a></h2><p>Close and reopen your terminal, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>✅ <strong>Checkpoint:</strong> each command prints a version number, and <code>node --version</code> prints <code>v22</code> or higher (anything from <code>v20.12</code> works).</p><h2 id="tell-git-who-you-are" tabindex="-1">Tell git who you are <a class="header-anchor" href="#tell-git-who-you-are" aria-label="Permalink to &quot;Tell git who you are&quot;">​</a></h2><p>Git records a name and email address with every commit. Use the private <strong>noreply</strong> address GitHub gives you, so your real email doesn&#39;t appear in public repositories. Find it under GitHub <strong>Settings</strong> → <strong>Emails</strong>; it ends in <code>@users.noreply.github.com</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[Your Name]&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[12345678+yourusername]@users.noreply.github.com&quot;</span></span></code></pre></div><p>Replace both values in square brackets with your own, and delete the brackets.</p><h2 id="sign-in-to-github-in-vs-code" tabindex="-1">Sign in to GitHub in VS Code <a class="header-anchor" href="#sign-in-to-github-in-vs-code" aria-label="Permalink to &quot;Sign in to GitHub in VS Code&quot;">​</a></h2><ol><li>In VS Code, click the <strong>Accounts</strong> icon (the person, bottom left) → <strong>Sign in with GitHub</strong>.</li><li>Your browser opens. Sign in to GitHub and approve the request, then allow the browser to return to VS Code.</li><li>The first time you push, Git may open the browser again to sign you in. That&#39;s expected.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Never type your GitHub password into a terminal. GitHub doesn&#39;t accept passwords there. Sign-in always happens in the browser.</p></div><h2 id="github-copilot-on-your-computer" tabindex="-1">GitHub Copilot on your computer <a class="header-anchor" href="#github-copilot-on-your-computer" aria-label="Permalink to &quot;GitHub Copilot on your computer&quot;">​</a></h2><p>Copilot is built into VS Code. Once you&#39;re signed in with GitHub, click the <strong>Copilot</strong> icon in the status bar, or <strong>Use AI Features</strong> if it&#39;s offered. It uses the same plan (Free or Student) and the same monthly allowance as in Codespaces. The modes and approvals work the same way: see <a href="./codespaces.html#turn-on-github-copilot-free">GitHub Codespaces: Turn on GitHub Copilot Free</a>.</p><ul><li>Your privacy setting on github.com applies here too (<a href="./privacy-settings.html#github-copilot">Privacy settings: GitHub Copilot</a>).</li><li>To stop VS Code sending usage statistics: <strong>Settings</strong> → search <code>telemetry</code> → set <strong>Telemetry Level</strong> to <strong>off</strong>.</li><li>To turn AI off for AI-off activities: <strong>Settings</strong> → search <code>disable AI features</code> → tick <strong>Chat: Disable AI Features</strong>.</li></ul><h2 id="get-a-project-onto-your-computer" tabindex="-1">Get a project onto your computer <a class="header-anchor" href="#get-a-project-onto-your-computer" aria-label="Permalink to &quot;Get a project onto your computer&quot;">​</a></h2><p><strong>Cloning</strong> means downloading a repository, with its full history, so you can work on it locally.</p><ol><li><p>Make a folder for all your course work, for example <code>vc101</code> inside your Documents folder. Keep course projects only there.</p></li><li><p>On github.com, open your repository, click <strong>Code</strong> → <strong>Local</strong> tab, and copy the <strong>HTTPS</strong> address.</p></li><li><p>In a terminal (use <code>cd</code> to go into your <code>vc101</code> folder first):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/[your-username]/[your-repo].git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [your-repo]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Replace the parts in square brackets, and delete the brackets.</p><p>Or, in VS Code: Command Palette → <strong>Git: Clone</strong> → paste the address → choose your <code>vc101</code> folder.</p></li></ol><p>To start a <strong>new</strong> project from a course starter, first create a new, empty repository on GitHub and clone it, then run the degit command from <a href="./codespaces.html#start-a-project-from-a-starter">GitHub Codespaces: Start a project from a starter</a> inside that freshly cloned folder. The same command works on your computer.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>degit&#39;s <code>--force</code> option overwrites files with the same names without asking. Run it <strong>only</strong> in a brand-new, empty repository&#39;s folder, never in an existing project such as your Project 1 or capstone. Check first: <code>git log --oneline</code> should show a single commit.</p></div><h2 id="run-the-starters" tabindex="-1">Run the starters <a class="header-anchor" href="#run-the-starters" aria-label="Permalink to &quot;Run the starters&quot;">​</a></h2><p>Static sites (weeks 1–8):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Then open <code>http://localhost:8000</code> in your browser. (<strong>localhost</strong> means &quot;this computer&quot;. On Windows, use <code>py -m http.server 8000</code>.)</p><p>Node starters (week 9 onward):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Then open <code>http://localhost:3000</code>. Fill in <code>.env</code> as the week 9 lab explains. On Windows PowerShell, replace the <code>cp</code> line with <code>Copy-Item .env.example .env</code>. Codespaces secrets don&#39;t reach your computer, so locally you always use <code>.env</code>.</p><p>Stop a running server with <code>Ctrl+C</code>.</p><h2 id="keep-your-laptop-and-codespaces-in-step" tabindex="-1">Keep your laptop and Codespaces in step <a class="header-anchor" href="#keep-your-laptop-and-codespaces-in-step" aria-label="Permalink to &quot;Keep your laptop and Codespaces in step&quot;">​</a></h2><p>Your repository on GitHub is the single source of truth. Before you start work in one place, <strong>pull</strong>. When you stop, <strong>commit and push</strong>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre></div><p>If you edit the same file in a codespace and on your laptop without pushing and pulling in between, git will report a <strong>conflict</strong>. That&#39;s fixable, but it&#39;s easier to avoid.</p><h2 id="when-to-stay-in-codespaces" tabindex="-1">When to stay in Codespaces <a class="header-anchor" href="#when-to-stay-in-codespaces" aria-label="Permalink to &quot;When to stay in Codespaces&quot;">​</a></h2><p>Stay in Codespaces (or come back to it) when:</p><ul><li><strong>You&#39;re doing agent work (weeks 11–16).</strong> A codespace is a sandbox: an agent there can&#39;t reach your personal files, passwords or other projects. That&#39;s safety contract rule 4.</li><li><strong>Your computer is managed by work or school,</strong> or you can&#39;t install software on it.</li><li><strong>Your computer is low on memory or disk space,</strong> or it&#39;s a Chromebook.</li><li><strong>You&#39;re stuck and need help.</strong> Your instructor can reproduce problems in a codespace exactly; a local setup has endless small differences.</li><li><strong>It&#39;s an in-class activity,</strong> unless your instructor says otherwise.</li></ul><p>Local setup is a good choice when you have no reliable internet, when your Codespaces hours are used up for the month, when you want to try running AI models on your own machine (see the Ollama row in <a href="./../TOOLS.html">Tool Handout</a>; it needs a lot of memory), or after the course, to keep building.</p><p>Back to <a href="./">Week 0 pre-work</a> · <a href="./codespaces.html">Codespaces guide</a></p>`,51)])])}const g=s(i,[["render",n]]);export{u as __pageData,g as default};
